from __future__ import annotations

from math import inf
from typing import Dict, List, Tuple

from examples.cvrp.instance import CVRPInstance


def variables(inst) -> dict[str, tuple[float, float, str]]:
    n = inst.n_customers
    vars_: dict[str, tuple[float, float, str]] = {}

    # Arc variables on the augmented graph {0..n}.
    for i in range(n + 1):
        for j in range(n + 1):
            if i != j:
                vars_[f"x_{i}_{j}"] = (0.0, 1.0, "binary")

    # Load variables for customers.
    for i in inst.customers:
        vars_[f"u_{i}"] = (float(inst.demand[i]), float(inst.capacity), "continuous")

    return vars_


def structural_variables(inst) -> list[str]:
    n = inst.n_customers
    return [f"x_{i}_{j}" for i in range(n + 1) for j in range(n + 1) if i != j]


def _route_cost(inst: CVRPInstance, route: tuple[int, ...]) -> float:
