    while j > 0:
        i = prev[j]
        if i < 0:
            break
        routes.append(tour[i:j])
        j = i
    routes.reverse()
    return routes, dp[n]


def to_assignment(inst, sol) -> dict[str, float]:
    tour = tuple(int(c) for c in sol)
    routes, _ = _split_dp(inst, tour)

    x: dict[str, float] = {name: 0.0 for name in structural_variables(inst)}
    u: dict[str, float] = {}

    for route in routes:
        if not route:
            continue
        x[f"x_0_{route[0]}"] = 1.0
        load = 0.0
        prev = 0
        for c in route:
            x[f"x_{prev}_{c}"] = 1.0
            load += float(inst.demand[c])
            u[f"u_{c}"] = load
            prev = c
        x[f"x_{prev}_0"] = 1.0

    # Ensure all customer loads are present even if isolated.
    for c in inst.customers:
        u.setdefault(f"u_{c}", float(inst.demand[c]))

    out = {}
    out.update(x)
    out.update(u)
    return out


def aux_values(inst, sol) -> dict[str, float]:
    tour = tuple(int(c) for c in sol)
    routes, _ = _split_dp(inst, tour)

    vals: dict[str, float] = {}
    for c in inst.customers:
        vals[f"u_{c}"] = float(inst.demand[c])

    # Customer loads along the decoded routes.
    for route in routes:
        load = 0.0
        for c in route:
            load += float(inst.demand[c])
            vals[f"u_{c}"] = load

    return vals


def from_assignment(inst, x) -> "sol":
    # Reconstruct routes from the successor relation, then concatenate them.
    succ = {}
    for i in range(inst.n_customers + 1):
        for j in range(inst.n_customers + 1):
            if i != j and x.get(f"x_{i}_{j}", 0.0) > 0.5:
                succ[i] = j

    routes: list[list[int]] = []
    used = set()
    for start in range(1, inst.n_customers + 1):
        if x.get(f"x_0_{start}", 0.0) > 0.5 and start not in used:
            route = []
            cur = start
            while cur != 0 and cur not in used:
                route.append(cur)
                used.add(cur)
                cur = succ.get(cur, 0)
            routes.append(route)

    # Any remaining customers are appended deterministically.
    remaining = [c for c in inst.customers if c not in used]
    for c in remaining:
        routes.append([c])

    tour: list[int] = []
    for r in routes:
        tour.extend(r)
    return tuple(tour)


def violations(inst, sol) -> dict[str, float]:
