def constraint_families(inst) -> dict[str, list[tuple[dict[str, float], str, float]]]:
    fam: dict[str, list[tuple[dict[str, float], str, float]]] = {"visita": [], "capacidad": []}
    n = inst.n_customers

    # Each customer has exactly one predecessor and one successor.
    for j in inst.customers:
        fam["visita"].append(({f"x_{i}_{j}": 1.0 for i in range(n + 1) if i != j}, "==", 1.0))
        fam["visita"].append(({f"x_{j}_{k}": 1.0 for k in range(n + 1) if k != j}, "==", 1.0))

    # Depot balance: same number of departures and returns.
    fam["visita"].append(({f"x_0_{j}": 1.0 for j in inst.customers}, "==", {f"x_{i}_0": 1.0 for i in inst.customers}))  # type: ignore

    # Capacity / load propagation (MTZ-like).
    Q = float(inst.capacity)
    for i in inst.customers:
        fam["capacidad"].append(({f"u_{i}": 1.0}, ">=", float(inst.demand[i])))
        fam["capacidad"].append(({f"u_{i}": 1.0}, "<=", Q))
        for j in inst.customers:
            if i != j:
                fam["capacidad"].append(
                    ({f"u_{j}": 1.0, f"u_{i}": -1.0, f"x_{i}_{j}": -Q}, ">=", float(inst.demand[j]) - Q)
                )
        fam["capacidad"].append(({f"u_{i}": 1.0, f"x_0_{i}": -Q}, ">=", float(inst.demand[i]) - Q))

    return fam


def objective_terms(inst) -> dict[str, tuple[dict[str, float], float]]:
    terms: dict[str, tuple[dict[str, float], float]] = {}
    n = inst.n_customers

    coef: dict[str, float] = {}
    for i in range(n + 1):
        for j in range(n + 1):
            if i != j:
                coef[f"x_{i}_{j}"] = float(inst.dist(i, j))
    terms["distancia"] = (coef, 0.0)
    return terms


def variable_groups(inst) -> dict[str, list[str]]:
    n = inst.n_customers
    groups: dict[str, list[str]] = {
        "depot": [],
        "first_half": [],
        "second_half": [],
        "load": [],
    }

    customers = list(inst.customers)
    mid = max(1, len(customers) // 2)
    first = set(customers[:mid])
    second = set(customers[mid:])

    for i in range(n + 1):
        for j in range(n + 1):
            if i == j:
                continue
            name = f"x_{i}_{j}"
            if i == 0 or j == 0:
                groups["depot"].append(name)
            elif i in first or j in first:
                groups["first_half"].append(name)
            else:
                groups["second_half"].append(name)

    groups["load"] = [f"u_{i}" for i in inst.customers]
    return groups
